css:
.fw {
  width: min(620px, 100%);
  padding: 28px;
  border: 1px solid var(--border); border-radius: 14px; background: var(--bg-alt);
}
.fw-titulo { margin: 0 0 6px; font-family: 'Sora', sans-serif; font-size: 20px; }
.fw-sub { margin: 0 0 22px; font-size: 13px; color: var(--text-muted); line-height: 1.5; }

.fw-grade { display: grid; gap: 14px; }
@media (min-width: 640px) { .fw-grade { grid-template-columns: 1fr 1fr; } }
.fw-inteiro { grid-column: 1 / -1; }

.fw-campo { display: flex; flex-direction: column; gap: 6px; }
.fw-campo label { font-size: 12px; color: var(--text-muted); }

.fw input, .fw select, .fw textarea {
  width: 100%; padding: 11px 13px;
  border: 1px solid var(--border); border-radius: 8px;
  /* Em seção de fundo claro, input branco some e sobra só a borda: o campo
     usa a cor de superfície, nunca branco puro. */
  background: var(--bg);
  color: var(--text); font-family: inherit; font-size: 14px;
  outline: none;
}
.fw input:focus, .fw select:focus, .fw textarea:focus { border-color: var(--accent); }
.fw textarea { resize: vertical; }

.fw-enviar {
  margin-top: 20px; width: 100%; padding: 14px;
  border: none; border-radius: 8px;
  background: var(--accent); color: var(--bg);
  font-family: inherit; font-size: 14px; font-weight: 600; cursor: pointer;
}
.fw-enviar:hover { background: var(--accent-hover); }

.fw-previa {
  margin: 18px 0 0; padding: 14px;
  border: 1px dashed var(--border); border-radius: 8px;
  background: var(--bg);
  font-family: 'JetBrains Mono', monospace; font-size: 12px; line-height: 1.6;
  color: var(--text-muted);
  white-space: pre-wrap;
}
.fw-previa[hidden] { display: none; }

js:
export function iniciarFormWhatsapp(form, aoMontar) {
  form.addEventListener('submit', (e) => {
    // O navegador já barrou o envio se faltava campo obrigatório: quando o
    // submit chega aqui, a validação nativa passou. Nenhuma linha de JS de
    // validação é necessária.
    e.preventDefault()

    const dados = new FormData(form)
    const linhas = []
    for (const [campo, valor] of dados.entries()) {
      // Campo vazio não entra: "Telefone:" seguido de nada polui a conversa.
      if (String(valor).trim()) linhas.push(`*${campo}:* ${String(valor).trim()}`)
    }

    const mensagem = linhas.join('\n')
    // encodeURIComponent é obrigatório: o texto tem quebra de linha e acento,
    // e concatenação crua quebra a URL na primeira delas.
    const url = `https://wa.me/${form.dataset.whatsapp}?text=${encodeURIComponent(mensagem)}`

    if (aoMontar) aoMontar(mensagem, url)
    else window.open(url, '_blank', 'noopener')
  })
}

demo:
// No site, o envio abre a conversa. Aqui a mensagem é mostrada na tela,
// porque o preview roda isolado e não navega pra fora.
const form = document.querySelector('.fw')
const previa = form.querySelector('.fw-previa')
iniciarFormWhatsapp(form, (mensagem, url) => {
  previa.hidden = false
  previa.textContent = mensagem + '\n\n→ ' + url.slice(0, 60) + '...'
})
